/*
 * LPC2148 SmartX Board - ADC Potentiometer
 * Read potentiometer on AIN0 (P0.26) using ADC0
 * Send results to Serial Monitor via UART0
 */

#include <LPC214x.h>

void uart0_init(void) {
    PINSEL0 |= (1 << 0) | (1 << 2);  // P0.2=TXD0, P0.3=RXD0
    U0LCR = 0x83;                     // 8N1, DLAB=1
    U0DLL = 0x06;                     // 9600 baud @ 60MHz PCLK
    U0DLM = 0x00;
    U0LCR = 0x03;                     // DLAB=0, 8N1
}

void uart0_tx(char c) {
    while (!(U0LSR & 0x20));          // Wait for THR empty
    U0THR = c;
}

void uart0_print(const char *s) {
    while (*s) uart0_tx(*s++);
}

void uart0_printNum(int n) {
    char buf[8];
    int i = 0;
    if (n == 0) { uart0_tx('0'); return; }
    while (n > 0) { buf[i++] = '0' + (n % 10); n /= 10; }
    while (i > 0) uart0_tx(buf[--i]);
}

int main(void) {
    uart0_init();
    AD0CR = (1 << 21) | (1 << 0);    // PDN=1, select channel 0
    uart0_print("LPC2148 ADC Demo\r\n");
    while (1) {
        AD0CR |= (1 << 24);          // Start conversion
        while (!(AD0GDR & (1 << 31)));// Wait for DONE
        int val = (AD0GDR >> 6) & 0x3FF;
        uart0_print("AIN0 = ");
        uart0_printNum(val);
        uart0_print("\r\n");
        AD0CR &= ~(1 << 24);         // Stop
        delay_ms(500);
    }
}
